using System;using System.IO;using System.Diagnostics;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace SeraphimLuxury {
 partial class MainWindow {
  internal void CheckCombined14(){var a=new AppEntry {Id="installed-fixture-social",Name="Instagram",Target="C:\\owned-fixture.exe"};preferences.Apps.Add(a);AddUsage(a.Id,45,DateTime.Today);AddUsage("web:www.instagram.com",30,DateTime.Today);if(ControlCatalog14.Usage(preferences,a,DateTime.Today)!=75)throw new Exception("Temps natif et Web combiné");var wire=BrowserRequest(new BridgeRequest{action="status"});if(!System.Linq.Enumerable.Any(wire.usage,u=>u.AppId=="social-instagram"&&u.Seconds==45))throw new Exception("Association du temps natif à la plateforme Web");}
  internal void IsolatePolicy14(AppEntry entry){preferences.Apps=new List<AppEntry>{entry};preferences.SocialPassage=preferences.NativeContentLock=false;var policy=ControlCatalog14.Policy(preferences,entry);policy.LimitBlock=true;policy.DailyLimitMinutes=1;Session.Activate();guard.Activate();}
  internal bool LimitDenied14 {get{return NativeDenied(preferences.Apps[0]);}}
  internal void LimitReached14(){AddUsage(preferences.Apps[0].Id,65,DateTime.Today);guard.Tick();}
 }
 static class Policy14Tests {
  public static int Run(string dir){Directory.CreateDirectory(dir);var app=new Application {ShutdownMode=ShutdownMode.OnExplicitShutdown};var store=new PreferenceStore(Path.Combine(dir,"preferences.json"));store.Save(Preferences.Defaults());var w=new MainWindow(store,true){Opacity=0,ShowInTaskbar=false};app.MainWindow=w;Process worker=null;int stage=0;string marker=Path.Combine(dir,"worker.release");var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(500)};timer.Tick+=delegate{try{switch(stage++){
   case 0:w.CheckCombined14();if(File.Exists(marker))File.Delete(marker);var target=Path.Combine(dir,"SeraphimTestWorker.exe");if(!File.Exists(target))throw new Exception("Owned worker missing");w.IsolatePolicy14(new AppEntry {Id="own-limit",Name="Owned fixture",Target=Path.Combine(dir,"synthetic-shortcut.lnk"),Executable=target});if(w.LimitDenied14)throw new Exception("Aucune limite avant usage");worker=Process.Start(new ProcessStartInfo(target,"\""+marker+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});break;
   case 1:w.LimitReached14();if(!w.LimitDenied14||w.ToolsHeld!=1)throw new Exception("Le raccourci doit être reconnu via son exécutable et mis en pause à la limite");File.WriteAllText(marker,"");break;
   case 2:if(worker.HasExited)throw new Exception("Le processus doit attendre réellement");w.PassageInput.Text=w.CurrentPassage.Text;w.PassageConfirm.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(!worker.WaitForExit(3000)||w.ToolsHeld!=0)throw new Exception("Le passage exact doit donner une reprise temporaire");w.Deactivate();if(w.LimitDenied14)throw new Exception("Les limites doivent être inactives en veille");timer.Stop();w.Close();File.WriteAllText(Path.Combine(dir,"policy14-test.txt"),"PASS limite quotidienne par application, raccourci .lnk lié à son .exe, compteurs natifs / Web combinés, pause effective du processus isolé, recopie, reprise et veille libre.");app.Shutdown();break;
  }}catch(Exception ex){timer.Stop();w.Deactivate();if(worker!=null&&!worker.HasExited){File.WriteAllText(marker,"");worker.WaitForExit(3000);}w.Close();File.WriteAllText(Path.Combine(dir,"policy14-test.txt"),"FAIL "+ex);app.Shutdown(1);}};w.Loaded+=delegate{timer.Start();};return app.Run(w);}
 }
}
